    (, int256 quotePrice, , , ) = quote.latestRoundData();

    // Assuming the prices are in USD, you could check if they are within a reasonable range of each other
    require(basePrice > 0 && quotePrice > 0, "Invalid prices from oracles");
    // Example tolerance check, adjust according to your application's requirements
    int256 tolerance = 1e8; // Adjust this tolerance level as needed
    require(
